BEGIN TRANSACTION;
CREATE TABLE appeal (
    appeal_id INTEGER PRIMARY KEY,
    appeal_ref TEXT NOT NULL UNIQUE,
    case_id INTEGER NOT NULL REFERENCES case_record(case_id),
    original_decision_id INTEGER NOT NULL REFERENCES decision(decision_id),
    grounds TEXT NOT NULL CHECK (length(trim(grounds)) > 0),
    submitted_at TEXT NOT NULL,
    appeal_status TEXT NOT NULL
        CHECK (appeal_status IN (
            'submitted', 'under_independent_review', 'upheld',
            'overturned', 'partially_upheld', 'closed'
        )),
    outcome TEXT
);
CREATE TABLE appeal_review (
    appeal_review_id INTEGER PRIMARY KEY,
    appeal_id INTEGER NOT NULL REFERENCES appeal(appeal_id),
    reviewer_id INTEGER NOT NULL REFERENCES reviewer(reviewer_id),
    review_rationale TEXT NOT NULL CHECK (length(trim(review_rationale)) > 0),
    review_outcome TEXT NOT NULL
        CHECK (review_outcome IN ('upheld', 'overturned', 'partially_upheld')),
    reviewed_at TEXT NOT NULL,
    UNIQUE (appeal_id, reviewer_id)
);
CREATE TABLE assessment (
    assessment_id INTEGER PRIMARY KEY,
    assessment_ref TEXT NOT NULL UNIQUE,
    title TEXT NOT NULL,
    assessment_type TEXT NOT NULL,
    opens_at TEXT NOT NULL,
    closes_at TEXT NOT NULL,
    created_at TEXT NOT NULL,
    CHECK (opens_at < closes_at)
);
CREATE TABLE audit_event (
    event_id INTEGER PRIMARY KEY,
    case_id INTEGER NOT NULL REFERENCES case_record(case_id),
    event_type TEXT NOT NULL,
    actor_type TEXT NOT NULL,
    actor_id TEXT,
    occurred_at TEXT NOT NULL,
    previous_state TEXT,
    new_state TEXT,
    event_details TEXT NOT NULL
);
CREATE TABLE case_record (
    case_id INTEGER PRIMARY KEY,
    case_ref TEXT NOT NULL UNIQUE,
    submission_id INTEGER NOT NULL REFERENCES submission(submission_id),
    similarity_report_id INTEGER NOT NULL REFERENCES similarity_report(similarity_report_id),
    opened_at TEXT NOT NULL,
    case_status TEXT NOT NULL
        CHECK (case_status IN (
            'open', 'assigned', 'under_review', 'decision_recorded',
            'appealed', 'under_independent_review', 'closed'
        )),
    priority TEXT NOT NULL DEFAULT 'normal'
        CHECK (priority IN ('low', 'normal', 'high')),
    CHECK (case_id > 0)
);
CREATE TABLE decision (
    decision_id INTEGER PRIMARY KEY,
    case_id INTEGER NOT NULL REFERENCES case_record(case_id),
    reviewer_id INTEGER NOT NULL REFERENCES reviewer(reviewer_id),
    decision_type TEXT NOT NULL
        CHECK (decision_type IN ('no_breach', 'breach_found', 'inconclusive', 'overturned')),
    rationale TEXT NOT NULL CHECK (length(trim(rationale)) > 0),
    decided_at TEXT NOT NULL,
    integrity_rule_id INTEGER NOT NULL REFERENCES integrity_rule(integrity_rule_id)
);
CREATE TABLE evidence_item (
    evidence_item_id INTEGER PRIMARY KEY,
    evidence_ref TEXT NOT NULL UNIQUE,
    case_id INTEGER NOT NULL REFERENCES case_record(case_id),
    evidence_type TEXT NOT NULL,
    source_reference TEXT NOT NULL,
    description TEXT NOT NULL,
    added_at TEXT NOT NULL,
    added_by_reviewer_id INTEGER REFERENCES reviewer(reviewer_id)
);
CREATE TABLE integrity_rule (
    integrity_rule_id INTEGER PRIMARY KEY,
    rule_ref TEXT NOT NULL,
    rule_version INTEGER NOT NULL CHECK (rule_version > 0),
    threshold REAL NOT NULL CHECK (threshold >= 0 AND threshold <= 100),
    effective_from TEXT NOT NULL,
    effective_to TEXT,
    rule_description TEXT NOT NULL,
    UNIQUE (rule_ref, rule_version),
    CHECK (effective_to IS NULL OR effective_from < effective_to)
);
CREATE TABLE learner (
    learner_id INTEGER PRIMARY KEY,
    learner_ref TEXT NOT NULL UNIQUE,
    cohort TEXT NOT NULL,
    created_at TEXT NOT NULL,
    is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1))
);
CREATE TABLE reviewer (
    reviewer_id INTEGER PRIMARY KEY,
    reviewer_ref TEXT NOT NULL UNIQUE,
    role TEXT NOT NULL
        CHECK (role IN ('instructor', 'academic_administrator', 'support_staff', 'platform_administrator')),
    is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
    created_at TEXT NOT NULL
);
CREATE TABLE reviewer_assignment (
    assignment_id INTEGER PRIMARY KEY,
    case_id INTEGER NOT NULL REFERENCES case_record(case_id),
    reviewer_id INTEGER NOT NULL REFERENCES reviewer(reviewer_id),
    assigned_at TEXT NOT NULL,
    unassigned_at TEXT,
    assignment_reason TEXT NOT NULL,
    CHECK (unassigned_at IS NULL OR assigned_at < unassigned_at)
);
CREATE TABLE reviewer_conflict (
    conflict_id INTEGER PRIMARY KEY,
    case_id INTEGER NOT NULL REFERENCES case_record(case_id),
    reviewer_id INTEGER NOT NULL REFERENCES reviewer(reviewer_id),
    conflict_type TEXT NOT NULL,
    declared_at TEXT NOT NULL,
    resolution_status TEXT NOT NULL
        CHECK (resolution_status IN ('unresolved', 'resolved', 'recused')),
    resolution_note TEXT
);
CREATE TABLE similarity_report (
    similarity_report_id INTEGER PRIMARY KEY,
    report_ref TEXT NOT NULL UNIQUE,
    submission_id INTEGER NOT NULL REFERENCES submission(submission_id),
    integrity_rule_id INTEGER NOT NULL REFERENCES integrity_rule(integrity_rule_id),
    similarity_score REAL NOT NULL
        CHECK (similarity_score >= 0 AND similarity_score <= 100),
    generated_at TEXT NOT NULL,
    flag_status TEXT NOT NULL
        CHECK (flag_status IN ('not_flagged', 'flagged', 'reviewed', 'superseded')),
    evidence_reference TEXT
);
CREATE TABLE submission (
    submission_id INTEGER PRIMARY KEY,
    submission_ref TEXT NOT NULL UNIQUE,
    learner_id INTEGER NOT NULL REFERENCES learner(learner_id),
    assessment_id INTEGER NOT NULL REFERENCES assessment(assessment_id),
    submitted_at TEXT NOT NULL,
    content_hash TEXT NOT NULL,
    submission_status TEXT NOT NULL
        CHECK (submission_status IN ('submitted', 'withdrawn')),
    UNIQUE (learner_id, assessment_id, submitted_at)
);
CREATE INDEX idx_submission_learner
    ON submission(learner_id);
CREATE INDEX idx_submission_assessment
    ON submission(assessment_id);
CREATE INDEX idx_similarity_submission
    ON similarity_report(submission_id);
CREATE INDEX idx_case_status
    ON case_record(case_status);
CREATE INDEX idx_assignment_case
    ON reviewer_assignment(case_id, reviewer_id);
CREATE INDEX idx_decision_case
    ON decision(case_id, decided_at);
CREATE INDEX idx_audit_case_time
    ON audit_event(case_id, occurred_at);
CREATE TRIGGER trg_case_report_match_insert
BEFORE INSERT ON case_record
WHEN NOT EXISTS (
    SELECT 1 FROM similarity_report r
    WHERE r.similarity_report_id = NEW.similarity_report_id
      AND r.submission_id = NEW.submission_id
)
BEGIN
    SELECT RAISE(ABORT, 'Case submission must match report submission');
END;
CREATE TRIGGER trg_case_report_match_update
BEFORE UPDATE OF submission_id, similarity_report_id ON case_record
WHEN NOT EXISTS (
    SELECT 1 FROM similarity_report r
    WHERE r.similarity_report_id = NEW.similarity_report_id
      AND r.submission_id = NEW.submission_id
)
BEGIN
    SELECT RAISE(ABORT, 'Case submission must match report submission');
END;
CREATE TRIGGER trg_assignment_conflict_insert
BEFORE INSERT ON reviewer_assignment
WHEN EXISTS (
    SELECT 1 FROM reviewer_conflict c
    WHERE c.case_id = NEW.case_id
      AND c.reviewer_id = NEW.reviewer_id
      AND c.resolution_status IN ('unresolved', 'recused')
)
BEGIN
    SELECT RAISE(ABORT, 'Conflicted reviewer cannot be assigned');
END;
CREATE TRIGGER trg_decision_conflict_insert
BEFORE INSERT ON decision
WHEN EXISTS (
    SELECT 1 FROM reviewer_conflict c
    WHERE c.case_id = NEW.case_id
      AND c.reviewer_id = NEW.reviewer_id
      AND c.resolution_status IN ('unresolved', 'recused')
)
BEGIN
    SELECT RAISE(ABORT, 'Conflicted reviewer cannot record a decision');
END;
CREATE TRIGGER trg_decision_conflict_update
BEFORE UPDATE OF case_id, reviewer_id ON decision
WHEN EXISTS (
    SELECT 1 FROM reviewer_conflict c
    WHERE c.case_id = NEW.case_id
      AND c.reviewer_id = NEW.reviewer_id
      AND c.resolution_status IN ('unresolved', 'recused')
)
BEGIN
    SELECT RAISE(ABORT, 'Conflicted reviewer cannot record a decision');
END;
CREATE TRIGGER trg_appeal_terminal_insert
BEFORE INSERT ON appeal
WHEN NEW.appeal_status IN ('closed', 'upheld', 'overturned', 'partially_upheld')
BEGIN
    SELECT RAISE(ABORT, 'Create appeal first; review it before completion');
END;
CREATE TRIGGER trg_appeal_terminal_update
BEFORE UPDATE OF appeal_status ON appeal
WHEN NEW.appeal_status IN ('closed', 'upheld', 'overturned', 'partially_upheld')
 AND OLD.appeal_status <> NEW.appeal_status
 AND NOT EXISTS (
    SELECT 1
    FROM appeal_review ar
    JOIN decision d ON d.decision_id = (
        SELECT a.original_decision_id
        FROM appeal a
        WHERE a.appeal_id = NEW.appeal_id
    )
    WHERE ar.appeal_id = NEW.appeal_id
      AND ar.reviewer_id <> d.reviewer_id
)
BEGIN
    SELECT RAISE(ABORT, 'Appeal requires independent review before completion');
END;
CREATE TRIGGER trg_appeal_review_independent
BEFORE INSERT ON appeal_review
WHEN EXISTS (
    SELECT 1
    FROM appeal a
    JOIN decision d ON d.decision_id = a.original_decision_id
    WHERE a.appeal_id = NEW.appeal_id
      AND d.reviewer_id = NEW.reviewer_id
)
BEGIN
    SELECT RAISE(ABORT, 'Appeal reviewer must differ from original reviewer');
END;
CREATE TRIGGER trg_evidence_audit_required
BEFORE INSERT ON evidence_item
WHEN EXISTS (
    SELECT 1 FROM decision d WHERE d.case_id = NEW.case_id
)
AND NOT EXISTS (
    SELECT 1 FROM audit_event e
    WHERE e.case_id = NEW.case_id
      AND e.event_type = 'evidence_added'
      AND e.occurred_at = NEW.added_at
)
BEGIN
    SELECT RAISE(ABORT, 'Post-decision evidence requires a matching audit event');
END;
CREATE TRIGGER trg_audit_no_update
BEFORE UPDATE ON audit_event
BEGIN
    SELECT RAISE(ABORT, 'Audit events cannot be updated');
END;
CREATE TRIGGER trg_audit_no_delete
BEFORE DELETE ON audit_event
BEGIN
    SELECT RAISE(ABORT, 'Audit events cannot be deleted');
END;
CREATE TRIGGER trg_case_lifecycle
BEFORE UPDATE OF case_status ON case_record
WHEN NEW.case_status <> OLD.case_status
 AND NOT (
       (OLD.case_status = 'open' AND NEW.case_status = 'assigned')
    OR (OLD.case_status = 'assigned' AND NEW.case_status = 'under_review')
    OR (OLD.case_status = 'under_review' AND NEW.case_status = 'decision_recorded')
    OR (OLD.case_status = 'decision_recorded' AND NEW.case_status IN ('appealed', 'closed'))
    OR (OLD.case_status = 'appealed' AND NEW.case_status = 'under_independent_review')
    OR (OLD.case_status = 'under_independent_review' AND NEW.case_status = 'closed')
 )
BEGIN
    SELECT RAISE(ABORT, 'Invalid case lifecycle transition');
END;
COMMIT;
